```tsx
import { useEffect, useState } from "react";

type CountdownTimerProps = {
  seconds: number;
  onComplete?: () => void;
};

export function CountdownTimer({
  seconds,
  onComplete,
}: CountdownTimerProps) {
  const [remaining, setRemaining] = useState(Math.max(0, seconds));

  useEffect(() => {
    setRemaining(Math.max(0, seconds));
  }, [seconds]);

  useEffect(() => {
    if (remaining <= 0) {
      onComplete?.();
      return;
    }

    const timer = window.setTimeout(() => {
      setRemaining((current) => Math.max(0, current - 1));
    }, 1000);

    return () => window.clearTimeout(timer);
  }, [remaining, onComplete]);

  const minutes = Math.floor(remaining / 60);
  const secs = remaining % 60;
  const display = `${String(minutes).padStart(2, "0")}:${String(secs).padStart(
    2,
    "0",
  )}`;

  return (
    <div role="timer" aria-live="polite" aria-label={`${remaining} seconds left`}>
      {display}
    </div>
  );
}
```

Usage:

```tsx
<CountdownTimer
  seconds={90}
  onComplete={() => console.log("Countdown complete")}
/>
```

Changing `seconds` restarts timer. Repo has no React app, so component provided standalone rather than written into existing project.

